from database_support import *
checks=[]
def passed(name):checks.append(name);print('PASS '+name,flush=True)
def fails(query,code):
 r=run(query,False);assert not r['ok'] and code in r['error'],r

def reset():run("UPDATE notification_outbox SET state='cancelled',lease_id=NULL,lease_until=NULL;UPDATE notification_channels SET enabled=false;")
def destination(f):run("INSERT INTO notification_destinations(user_id,channel,recipient,verified_at,verification_reference,consent_at,active) VALUES("+literal(f['p']+'u')+",'email','fixture@example.invalid',1,'VERIFIED-TEST-FIXTURE',1,true);")
def enqueue(f,event='outbox-fixture'):return rpc('jana_notification_insert_once',event,f['p']+'u','عنوان الاختبار','رسالة الاختبار')
def claim():return val(rpc('jana_notification_claim','email','resend','a'*64))
def finish(j,**changes):
 result={'outcome':'submitted','retryable':False,'provider_id':'provider-fixture'};result.update(changes);return rpc('jana_notification_finish',j['id'],j['lease_id'],result)
def setup():
 reset();f=fixture();destination(f);run("UPDATE notification_channels SET provider_scope=repeat('a',64),enabled=true,max_attempts=8 WHERE channel='email';");val(enqueue(f));return f

