r=val(finish(j));assert r['state']=='submitted';assert val(finish(j))==r;fails(finish(j,provider_id='changed-provider-id'),'idempotency_conflict');assert claim() is None;assert val("SELECT count(*) FROM notification_attempts WHERE job_id="+literal(j['id'])+" AND event='finished';")==1;passed('acknowledgement retries return the durable result without duplicating delivery attempts')
fails('UPDATE notification_outbox SET recipient=\'another@example.invalid\' WHERE id='+literal(j['id'])+';','notification_payload_immutable');fails('DELETE FROM notification_attempts WHERE job_id='+literal(j['id'])+';','append_only');passed('delivery payloads and attempt evidence cannot be silently rewritten')
f=setup();assert val(rpc('jana_notification_claim','email','resend','b'*64)) is None;run("UPDATE notification_channels SET provider_scope=repeat('b',64) WHERE channel='email';");assert val(rpc('jana_notification_claim','email','resend','b'*64)) is None;run("UPDATE notification_channels SET provider_scope=repeat('a',64) WHERE channel='email';");j=claim();assert j['attempt']==1;val(finish(j));passed('sender scope changes cannot silently move an old job to another sending identity')
