f=setup();j=claim();run('UPDATE notification_outbox SET lease_until=0 WHERE id='+literal(j['id'])+';');second=claim();assert second['idempotency_key']==j['idempotency_key'] and second['attempt']==2;fails(finish(j),'notification_lease_stale');assert val("SELECT count(*) FROM notification_attempts WHERE job_id="+literal(j['id'])+" AND event='lease_expired' AND outcome='unknown';")==1;val(finish(second));passed('crashed worker leases expire into recorded uncertainty and fence stale acknowledgements')
f=setup();j=claim();run("UPDATE notification_outbox SET lease_until=0,attempt_count=max_attempts WHERE id="+literal(j['id'])+';');assert claim() is None;assert val('SELECT to_jsonb(state) FROM notification_outbox WHERE id='+literal(j['id'])+';')=='reconcile';passed('exhausted uncertain attempts require reconciliation instead of unbounded resend')
