for result in [{},{'outcome':None,'retryable':False},{'outcome':'submitted','retryable':False},{'outcome':'submitted','retryable':False,'provider_id':'ok','error_code':'PRIVATE'},{'outcome':'unknown','retryable':False,'error_code':'recipient@example.invalid'}]:fails(rpc('jana_notification_finish',j['id'],j['lease_id'],result),'notification_result_invalid')
val(finish(j));passed('invalid results and private free-text errors cannot enter the delivery audit')
f=setup();r=run('BEGIN;'+enqueue(f,'rolled-back-event')+'ROLLBACK;');assert r['ok'];assert val("SELECT count(*) FROM notifications WHERE dedupe_key='adapter:'||encode(digest(jsonb_build_array('rolled-back-event',"+literal(f['p']+'u')+")::text,'sha256'),'hex');")==0;passed('outer business transaction rollback also removes queued channel jobs')
overview=val(rpc('jana_notification_overview',f['atok']));assert len(overview['items'])<=50;assert all(not {'recipient','title','body','user_id','lease_id'}&set(x) for x in overview['items']);fails(rpc('jana_notification_overview',f['t']),'forbidden');run("UPDATE users SET role='support' WHERE id="+literal(f['p']+'a')+';');assert val(rpc('jana_notification_overview',f['atok']))['channels'];passed('support sees bounded operational states without recipient content or worker leases')
assert val("SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'jana_notification_%' AND (has_function_privilege('anon',oid,'EXECUTE') OR has_function_privilege('authenticated',oid,'EXECUTE'));")==0;assert val('SELECT jana_deep_health();')['ok'];reset();passed('worker functions remain service-only and commerce invariants unchanged')
